func (p *CharacterInventory) ItemsCount() int { return int(p.ItemCount()) }
func (p *CharacterInventory) Items(i, stride int) *StoredItem {
	count := int(p.ItemCount())
	if stride <= 0 {
		return nil
	}
	start := 6 + i*stride
	if i < 0 || i >= count || start+stride > len(p.d) {
		return nil
	}
	return AsStoredItem(p.d[start:])
}

